changeSet.sql:
DROP MATERIALIZED VIEW IF EXISTS mv_daily_recon_summary;
CREATE MATERIALIZED VIEW mv_daily_recon_summary WITH (fillfactor = 90) AS SELECT t.trade_date, cp.region, t.asset_class, COUNT(*) AS total_trades, COUNT(*) FILTER (WHERE t.status = 'SETTLED') AS matched_trades, COALESCE(SUM(rb.open_count), 0) AS open_breaks, COALESCE(ROUND(SUM(t.quantity * t.price)::NUMERIC, 2), 0) AS gross_notional, ROUND( COUNT(*) FILTER (WHERE t.status = 'SETTLED') * 100.0 / NULLIF(COUNT(*), 0), 2 ) AS match_rate_pct FROM trades t JOIN counterparties cp ON cp.id = t.counterparty_id LEFT JOIN ( SELECT trade_id, COUNT(*) FILTER (WHERE status = 'OPEN') AS open_count FROM recon_breaks GROUP BY trade_id ) rb ON rb.trade_id = t.id WHERE t.deleted_at IS NULL GROUP BY t.trade_date, cp.region, t.asset_class WITH NO DATA;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary ON mv_daily_recon_summary (trade_date, region, asset_class);
REFRESH MATERIALIZED VIEW mv_daily_recon_summary;
